// Filtra apenas mensagens de áudio recebidas
// Rejeita lotes com múltiplos áudios (segurança)

const items = $('Webhook Evolution API').all() ;
const audioItems = [];

for (const item of items) {
  const data = item.json;
  const body = data.body || data;

  if (body.event !== 'messages.upsert') continue;

  const message = body?.data?.message;
  const key = body?.data?.key;

  if (!message?.audioMessage) continue;

  // key.remoteJid = identificador do chat (pode ser LID ou número)
  const remoteJid = key.remoteJid;

  audioItems.push({
    messageId: key.id,
    remoteJid: remoteJid,
    pushName: body?.data?.pushName || 'Desconhecido',
    instanceName: body?.instance || '',
    audioSeconds: message.audioMessage.seconds || 0,
    mimetype: message.audioMessage.mimetype || 'audio/ogg',
    isPtt: message.audioMessage.ptt || false
  });
}

if (audioItems.length === 0) return [];

// Sinaliza múltiplos áudios para rejeição no próximo nó
if (audioItems.length > 1) {
  return [{
    json: {
      multipleAudios: true,
      audioCount: audioItems.length,
      remoteJid: audioItems[0].remoteJid,
      instanceName: audioItems[0].instanceName
    }
  }];
}

return [{ json: { ...audioItems[0], multipleAudios: false } }];

// Converte o áudio base64 retornado pela Evolution API em dados binários
// para enviar ao Gemini

const item = $input.first();
const base64Data = item.json.base64;
const mimetype = item.json.mimetype || 'audio/ogg';

if (!base64Data) {
  throw new Error('Nenhum dado de áudio base64 encontrado na resposta da Evolution API. Verifique se DATABASE_SAVE_DATA_NEW_MESSAGE=true está configurado.');
}

// Preserva os dados do item anterior (messageId, remoteJid, etc.)
// Precisamos pegar do nó "Filtrar Mensagens de Áudio"
const filtroData = $('Filtrar Mensagens de Áudio').first().json;

return {
  json: {
    remoteJid: filtroData.remoteJid,
    pushName: filtroData.pushName,
    instanceName: filtroData.instanceName,
    audioSeconds: filtroData.audioSeconds
  },
  binary: {
    audio: {
      data: base64Data,
      mimeType: mimetype,
      fileName: 'audio_pescador.ogg'
    }
  }
};

// Sanitiza a transcrição antes de enviar ao AI Agent
// Camada de defesa contra prompt injection - PT-BR e EN

const transcription = $json.content?.parts?.[0]?.text || '';

// Limite de tamanho - um anúncio de venda não precisa de mais de 500 chars
const MAX_LENGTH = 500;
const truncated = transcription.length > MAX_LENGTH;
const trimmed = truncated ? transcription.substring(0, MAX_LENGTH) : transcription;

// Padrões de prompt injection (inglês e português)
const injectionPatterns = [
  /ignore\s+(all\s+)?(previous|prior|above)\s+instructions?/i,
  /you\s+are\s+now\s+/i,
  /act\s+as\s+/i,
  /forget\s+(everything|all|previous)/i,
  /new\s+instructions?:/i,
  /\[system\]/i,
  /\[assistant\]/i,
  /system\s*prompt/i,
  /override\s+(your\s+)?instructions?/i,
  /jailbreak/i,
  /prompt\s*injection/i,
  /esqueça\s+(tudo|todas?\s+as?\s+instruções?)/i,
  /ignore\s+(todas?\s+as?\s+)?instruções?/i,
  /agora\s+você\s+é\s+/i,
  /finja\s+que\s+você\s+é\s+/i,
  /novas?\s+instruções?:/i,
  /mude\s+(seu\s+)?comportamento/i,
];

let sanitized = trimmed;
let injectionDetected = false;

for (const pattern of injectionPatterns) {
  if (pattern.test(sanitized)) {
    injectionDetected = true;
    sanitized = sanitized.replace(pattern, '[REMOVIDO]');
  }
}

return [{
  json: {
    ...$json,
    content: {
      parts: [{
        text: sanitized
      }]
    },
    _meta: {
      truncated,
      injectionDetected,
      originalLength: transcription.length
    }
  }
}];

const agentOutput = $json.output || '';

let parsed;
try {
  let cleaned = agentOutput.trim();
  if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```[a-z]*\n?/, '').replace(/\n?```$/, '');
  }
  parsed = JSON.parse(cleaned);

  // Garante que status é sempre um valor permitido
  if (!['ok', 'erro', 'fora_de_contexto'].includes(parsed.status)) {
    parsed = {
      status: 'erro',
      mensagem: 'Não consegui processar sua mensagem. Por favor, tente novamente enviando o áudio informando: tipo de peixe, quantidade ou peso, e o preço de venda.'
    };
  }
} catch (e) {
  parsed = {
    status: 'erro',
    mensagem: 'Não consegui processar sua mensagem. Por favor, tente novamente enviando o áudio informando: tipo de peixe, quantidade ou peso, e o preço de venda.'
  };
}

return [{ json: parsed }];

